// Parse and validate user request
return [
  {
    json: {
      userQuery: "Explain quantum computing in simple terms",
      context: "Educational content for high school students",
      requestId: `req_${Date.now()}`,
      timestamp: new Date().toISOString()
    }
  }
];

// Format prompt with retrieved context
const input = $input.first();
const externalData = items[0].json;

return [
  {
    json: {
      messages: [
        {
          role: "system",
          content: `You are an educational AI assistant. Context: ${input.json.context}`
        },
        {
          role: "user",
          content: `${input.json.userQuery}\n\nAdditional context: ${JSON.stringify(externalData)}`
        }
      ],
      model: "gpt-4",
      temperature: 0.7,
      max_tokens: 500,
      requestId: input.json.requestId
    }
  }
];

// OpenAI API call
const promptData = items[0].json;

return [
  {
    json: {
      id: `chatcmpl-${Math.random().toString(36).substr(2, 9)}`,
      object: "chat.completion",
      created: Math.floor(Date.now() / 1000),
      model: promptData.model,
      choices: [
        {
          index: 0,
          message: {
            role: "assistant",
            content: "Quantum computing is like having a super-powered calculator that can explore many possibilities at once. While regular computers use bits (0s and 1s), quantum computers use qubits that can be both 0 and 1 simultaneously through superposition. This allows them to solve certain complex problems much faster than traditional computers."
          },
          finish_reason: "stop"
        }
      ],
      usage: {
        prompt_tokens: 156,
        completion_tokens: 87,
        total_tokens: 243
      },
      requestId: promptData.requestId
    }
  }
];

// Quality evaluation guardrail
const completion = items[0].json;
const response = completion.choices[0].message.content;

// Calculate quality metrics
const wordCount = response.split(' ').length;
const hasNumbers = /\d/.test(response);
const sentenceCount = (response.match(/[.!?]/g) || []).length;

const metrics = {
  clarity: 0.92,
  accuracy: 0.88,
  relevance: 0.95,
  readability: 0.90,
  wordCount,
  sentenceCount,
  technicalTermsUsed: hasNumbers
};

const avgScore = (metrics.clarity + metrics.accuracy + metrics.relevance + metrics.readability) / 4;

return [
  {
    json: {
      ...completion,
      evaluation: metrics,
      qualityScore: avgScore,
      passed: avgScore >= 0.8
    }
  }
];

// Approved response handler
const data = items[0].json;

return [
  {
    json: {
      status: "approved",
      response: data.choices[0].message.content,
      model: data.model,
      metrics: {
        quality: data.qualityScore,
        tokens: data.usage.total_tokens,
        evaluation: data.evaluation
      },
      requestId: data.requestId,
      timestamp: new Date().toISOString()
    }
  }
];

// Rejected response handler
const data = items[0].json;

return [
  {
    json: {
      status: "rejected",
      reason: "Quality score below threshold",
      qualityScore: data.qualityScore,
      requestId: data.requestId,
      timestamp: new Date().toISOString()
    }
  }
];

// Aggregate workflow results
const results = items.map(item => item.json);

return [
  {
    json: {
      workflowComplete: true,
      totalRequests: results.length,
      results,
      completedAt: new Date().toISOString()
    }
  }
];
